/**
 * Stream A — F8 Viral Idea Engine: deterministic, explainable idea scoring.
 *
 * D94 applies: rule-based and deterministic — factors, weights, and
 * confidence degradation are computed from evidence, never generated by an
 * LLM. The returned score always travels with its factors; the verdict is
 * rule-labeled and NEVER a virality guarantee.
 *
 * Phase-2 linkage (D96): the `outlier_alignment` factor consumes
 * `outlier_videos.outlier_score` (descriptive latest-views ÷ sibling-median
 * multiples — note: the pinned `videos` table has no `outlier_score`
 * column; `outlier_videos` is the ideation surface that carries it).
 *
 * Pure module — no I/O, no network, no randomness. Server functions in
 * `ideas.functions.ts` assemble the evidence; this module does the math.
 */
import { type IdeaScore, type IdeaScoreFactor } from "../contracts";

/* ------------------------------------------------------------------ */
/* Inputs                                                              */
/* ------------------------------------------------------------------ */

/** Minimal idea shape the scorer needs (mirrors `video_ideas` columns). */
export interface IdeaScorerIdea {
  id: string;
  title: string;
  hook: string;
  angle: string;
  format: string;
  difficulty: string;
  safetyFlag: string;
}

/**
 * Phase-2 outlier evidence for one idea.
 * `matchedOutlierScores` are `outlier_videos.outlier_score` values for
 * outlier videos whose titles match the idea's keywords (matched server-side
 * in `ideas.functions.ts`); `matchedKeywords` names the keywords used so the
 * evidence string is auditable.
 */
export interface IdeaOutlierEvidence {
  matchedOutlierScores: number[];
  matchedKeywords: string[];
  /** Total outlier rows available in the idea's research project. */
  projectOutlierCount: number;
}

export interface IdeaScoreInput {
  idea: IdeaScorerIdea;
  outlier: IdeaOutlierEvidence;
}

/* ------------------------------------------------------------------ */
/* Factor weights (pinned; D99)                                        */
/* ------------------------------------------------------------------ */

export const IDEA_FACTOR_WEIGHTS = {
  outlier_alignment: 0.35,
  hook_strength: 0.25,
  feasibility: 0.2,
  safety: 0.2,
} as const;

export type IdeaFactorKey = keyof typeof IDEA_FACTOR_WEIGHTS;

const FACTOR_LABELS: Record<IdeaFactorKey, string> = {
  outlier_alignment: "Outlier alignment",
  hook_strength: "Hook strength",
  feasibility: "Feasibility",
  safety: "Safety",
};

/* ------------------------------------------------------------------ */
/* Small deterministic helpers                                         */
/* ------------------------------------------------------------------ */

const STOPWORDS = new Set(
  "a,an,the,and,or,but,of,to,in,on,for,with,by,at,from,as,is,are,was,were,be,been,being,it,its,this,that,these,those,you,your,we,our,they,their,he,she,how,what,why,when,where,who,will,can,should,would,do,does,did,not,no,yes,of,so,if,then,than,too,very,just,about,into,over,after,before,up,down,out,off,again,once,here,there,all,any,both,each,few,more,most,other,some,such,only,own,same".split(
    ",",
  ),
);

/** Deterministic keyword extraction: lowercase tokens, stopwords removed. */
export function extractIdeaKeywords(
  title: string,
  hook: string,
  angle: string,
  maxKeywords = 8,
): string[] {
  const counts = new Map<string, number>();
  const order: string[] = [];
  for (const text of [title, hook, angle]) {
    for (const raw of text.toLowerCase().split(/[^a-z0-9]+/)) {
      if (raw.length < 3 || STOPWORDS.has(raw)) continue;
      counts.set(raw, (counts.get(raw) ?? 0) + 1);
      if (!order.includes(raw)) order.push(raw);
    }
  }
  return order
    .sort((a, b) => (counts.get(b) ?? 0) - (counts.get(a) ?? 0) || a.localeCompare(b))
    .slice(0, maxKeywords);
}

function clamp01(v: number): number {
  if (!Number.isFinite(v)) return 0;
  return Math.max(0, Math.min(1, v));
}

function round2(v: number): number {
  return Math.round(v * 100) / 100;
}

const CURIOSITY_MARKERS = [
  "secret",
  "truth",
  "nobody",
  "never",
  "mistake",
  "warning",
  "shocking",
  "hidden",
  "banned",
  "exposed",
  "untold",
  "finally",
  "actually",
  "really",
];

/* ------------------------------------------------------------------ */
/* Factor computations                                                 */
/* ------------------------------------------------------------------ */

function outlierAlignmentFactor(ev: IdeaOutlierEvidence): IdeaScoreFactor {
  const scores = ev.matchedOutlierScores.filter((s) => Number.isFinite(s) && s > 0);
  if (scores.length === 0) {
    return {
      key: "outlier_alignment",
      label: FACTOR_LABELS.outlier_alignment,
      value: 0,
      weight: IDEA_FACTOR_WEIGHTS.outlier_alignment,
      evidence:
        ev.projectOutlierCount === 0
          ? "insufficient_data: this research project has no outlier videos yet — track channels and run outlier detection first"
          : `insufficient_data: no outlier videos matched the idea's keywords (${ev.matchedKeywords.join(", ") || "none extracted"})`,
    };
  }
  const top = Math.max(...scores);
  // 5x channel median or better saturates the factor; descriptive, not a prediction.
  const value = round2(clamp01(top / 5));
  const kw = ev.matchedKeywords.length > 0 ? ` (keywords: ${ev.matchedKeywords.join(", ")})` : "";
  return {
    key: "outlier_alignment",
    label: FACTOR_LABELS.outlier_alignment,
    value,
    weight: IDEA_FACTOR_WEIGHTS.outlier_alignment,
    evidence: `${scores.length} outlier video${scores.length === 1 ? "" : "s"} matched${kw}; top ${top.toFixed(1)}x channel median (descriptive, not a prediction)`,
  };
}

function hookStrengthFactor(idea: IdeaScorerIdea): IdeaScoreFactor {
  const hook = idea.hook.trim();
  if (!hook) {
    return {
      key: "hook_strength",
      label: FACTOR_LABELS.hook_strength,
      value: 0,
      weight: IDEA_FACTOR_WEIGHTS.hook_strength,
      evidence:
        "insufficient_data: no hook written yet — the hook is the first 3 seconds of the video",
    };
  }
  const words = hook.split(/\s+/).filter(Boolean);
  const checks: string[] = [];
  let value = 0;
  // Length sweet spot: 8–20 words gets full marks, tapering outside.
  if (words.length >= 8 && words.length <= 20) {
    value += 0.4;
    checks.push(`${words.length} words (8–20 sweet spot)`);
  } else if (words.length >= 4 && words.length <= 30) {
    value += 0.2;
    checks.push(`${words.length} words (near the 8–20 sweet spot)`);
  } else {
    checks.push(`${words.length} words (outside the 8–20 sweet spot)`);
  }
  const lower = hook.toLowerCase();
  const markers = CURIOSITY_MARKERS.filter((m) => lower.includes(m));
  if (markers.length > 0) {
    value += Math.min(0.3, 0.15 * markers.length);
    checks.push(`curiosity markers: ${markers.slice(0, 3).join(", ")}`);
  }
  if (/\?/.test(hook)) {
    value += 0.15;
    checks.push("asks a question");
  }
  if (/\d/.test(hook)) {
    value += 0.15;
    checks.push("uses a number");
  }
  return {
    key: "hook_strength",
    label: FACTOR_LABELS.hook_strength,
    value: round2(clamp01(value)),
    weight: IDEA_FACTOR_WEIGHTS.hook_strength,
    evidence: checks.join("; "),
  };
}

const DIFFICULTY_VALUE: Record<string, number> = {
  easy: 1,
  medium: 0.65,
  hard: 0.35,
};

function feasibilityFactor(idea: IdeaScorerIdea): IdeaScoreFactor {
  const key = idea.difficulty.trim().toLowerCase();
  const value = DIFFICULTY_VALUE[key] ?? 0.5;
  return {
    key: "feasibility",
    label: FACTOR_LABELS.feasibility,
    value: round2(value),
    weight: IDEA_FACTOR_WEIGHTS.feasibility,
    evidence:
      key in DIFFICULTY_VALUE
        ? `difficulty=${idea.difficulty}, format=${idea.format}`
        : `insufficient_data: unrecognized difficulty "${idea.difficulty}" — treated as medium`,
  };
}

function safetyFactor(idea: IdeaScorerIdea): IdeaScoreFactor {
  const flag = idea.safetyFlag.trim().toLowerCase();
  if (flag === "safe" || flag === "") {
    return {
      key: "safety",
      label: FACTOR_LABELS.safety,
      value: 1,
      weight: IDEA_FACTOR_WEIGHTS.safety,
      evidence: `safety_flag=${idea.safetyFlag || "safe"} — no flags`,
    };
  }
  if (flag === "review") {
    return {
      key: "safety",
      label: FACTOR_LABELS.safety,
      value: 0.5,
      weight: IDEA_FACTOR_WEIGHTS.safety,
      evidence: "safety_flag=review — needs a human safety check before production",
    };
  }
  return {
    key: "safety",
    label: FACTOR_LABELS.safety,
    value: 0.1,
    weight: IDEA_FACTOR_WEIGHTS.safety,
    evidence: `safety_flag=${idea.safetyFlag} — blocked or flagged content scores near zero; resolve the flag first`,
  };
}

/* ------------------------------------------------------------------ */
/* Confidence + verdict                                                */
/* ------------------------------------------------------------------ */

function confidenceFor(idea: IdeaScorerIdea, ev: IdeaOutlierEvidence): "high" | "medium" | "low" {
  const matched = ev.matchedOutlierScores.length;
  const hasHook = idea.hook.trim().length > 0;
  if (matched < 2 || !hasHook || ev.projectOutlierCount < 3) return "low";
  if (matched >= 5 && ev.projectOutlierCount >= 10 && hasHook) return "high";
  return "medium";
}

function verdictFor(
  total: number,
  confidence: "high" | "medium" | "low",
  factors: IdeaScoreFactor[],
): string {
  const weakest = [...factors].sort((a, b) => a.value * a.weight - b.value * b.weight)[0];
  const base =
    total >= 70
      ? "Strong evidence-backed idea"
      : total >= 45
        ? "Workable idea with gaps"
        : "Weak evidence — improve before producing";
  const tail =
    confidence === "low"
      ? " (low confidence: thin evidence — see insufficient_data factors)"
      : ` (confidence: ${confidence})`;
  const fix =
    weakest && weakest.value < 0.6
      ? ` Weakest: ${weakest.label.toLowerCase()} — ${weakest.evidence}.`
      : "";
  return `${base}${tail}.${fix} Rule-based score, not a virality prediction.`.trim();
}

/* ------------------------------------------------------------------ */
/* Public scorer                                                       */
/* ------------------------------------------------------------------ */

/**
 * Score an idea deterministically. Identical inputs → identical outputs.
 * Never a virality guarantee: the verdict says so explicitly.
 */
export function scoreIdea(input: IdeaScoreInput): IdeaScore {
  const factors: IdeaScoreFactor[] = [
    outlierAlignmentFactor(input.outlier),
    hookStrengthFactor(input.idea),
    feasibilityFactor(input.idea),
    safetyFactor(input.idea),
  ];
  const total = Math.round(factors.reduce((sum, f) => sum + f.value * f.weight, 0) * 100);
  const confidence = confidenceFor(input.idea, input.outlier);
  return {
    total: Math.max(0, Math.min(100, total)),
    factors,
    confidence,
    verdict: verdictFor(total, confidence, factors),
  };
}
